//! #636 design A, review round 2 owner folds: WR6 (container occurrences are an allow-list) and A21 (same-file helper chain roots, depth 2). The Strong rows fail on 430c0c20.

use super::taint_sink_strength_test::*;

#[test]
fn python_round_2_owner_folds() {
    assert_severities(&[
        py("WR6/A13 alias then append of a raw clause", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = []\n    v2 = vals\n    v2.append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6/A14 deque appendleft of a raw clause", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nfrom collections import deque\ndef h(session, req):\n    s = req.args['s']\n    vals = deque()\n    vals.appendleft(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6/A19 operator.setitem of a raw clause", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nimport operator\ndef h(session, req):\n    s = req.args['s']\n    vals = [1]\n    operator.setitem(vals, 0, literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6 list.append(vals, raw)", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = []\n    list.append(vals, literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6 vals.__iadd__ of a raw clause", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = []\n    vals.__iadd__([literal_column(s)])\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6 vals passed to a same-file helper that appends", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef add(v, s):\n    v.append(literal_column(s))\ndef h(session, req):\n    s = req.args['s']\n    vals = []\n    add(vals, s)\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6 subscript store of a raw clause", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = [1]\n    vals[0] = literal_column(s)\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6 nested lambda mutates through list.append", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = []\n    f = lambda: list.append(vals, literal_column(s))\n    f()\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6 nested def mutates through operator.setitem", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nimport operator\ndef h(session, req):\n    s = req.args['s']\n    vals = [1]\n    def g():\n        operator.setitem(vals, 0, literal_column(s))\n    g()\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6 del of the list", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    vals = []\n    del vals\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("WR6 loop over a list that a helper fills", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef add(v, s):\n    v.append(literal_column(s))\ndef h(session, req):\n    s = req.args['s']\n    cols = []\n    add(cols, s)\n    for c in cols:\n        x = req.args['x']  # SEED\n        session.execute(select(User).where(User.a == c, User.id == x))  # SINK\n", W),
        py("WR6 loop over an aliased list", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    cols = []\n    alias = cols\n    alias.append(literal_column(s))\n    for c in cols:\n        x = req.args['x']  # SEED\n        session.execute(select(User).where(User.a == c, User.id == x))  # SINK\n", W),
        py("recall: list filled with data by append", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req, rows):\n    vals = []\n    for r in rows:\n        vals.append(r.id)\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("recall: list filled with column attributes", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    vals = []\n    vals.append(User.id)\n    vals.extend([1, 2])\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("recall: loop over a proven local list", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req, rows):\n    cols = []\n    for r in rows:\n        cols.append(r.id)\n    for c in cols:\n        x = req.args['x']  # SEED\n        session.execute(select(User).where(User.a == c, User.id == x))  # SINK\n", S),
        py("recall: len(vals) beside the proven use", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    vals = [1, 2]\n    n = len(vals)\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("recall: sorted(vals) and a comprehension over it", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    vals = [1, 2]\n    ys = [v for v in sorted(vals)]\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("A21 raw same-file helper as chain root", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef base(session, s):\n    return session.query(User).order_by(literal_column(s))\ndef h(session, req):\n    s = req.args['s']\n    x = req.args['x']  # SEED\n    return base(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("A21 self.base_query method returning a raw chain", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass R:\n    def base_query(self, session, s):\n        return session.query(User).order_by(literal_column(s))\n    def h(self, session, req):\n        s = req.args['s']\n        x = req.args['x']  # SEED\n        return self.base_query(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("A21 depth-3 helper chain refuses", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef c(session, s):\n    return session.query(User).order_by(literal_column(s))\ndef b(session, s):\n    return c(session, s).order_by(User.id)\ndef a(session, s):\n    return b(session, s).order_by(User.id)\ndef h(session, req):\n    s = req.args['s']\n    x = req.args['x']  # SEED\n    return a(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("A21 recursive helper refuses", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef base(session, n):\n    if n:\n        return base(session, n - 1).order_by(User.id)\n    return session.query(User).order_by(User.id)\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return base(session, 2).filter(User.id == x).all()  # SINK\n", W),
        py("A21 helper with a bare return refuses", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef base(session, s):\n    if s:\n        return\n    return session.query(User).order_by(User.id)\ndef h(session, req):\n    s = req.args['s']\n    x = req.args['x']  # SEED\n    return base(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("A21 helper without a return refuses", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef base(session, s):\n    session.query(User).order_by(User.id)\ndef h(session, req):\n    s = req.args['s']\n    x = req.args['x']  # SEED\n    return base(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("A21 decorated helper refuses", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\n@cache\ndef base(session):\n    return session.query(User).order_by(User.id)\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return base(session).filter(User.id == x).all()  # SINK\n", W),
        py("A21 helper name rebound elsewhere refuses", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef base(session):\n    return session.query(User).order_by(User.id)\nbase = wrap(base)\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return base(session).filter(User.id == x).all()  # SINK\n", W),
        py("A21 decorated method refuses", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass R:\n    @cache\n    def base_query(self, session):\n        return session.query(User).order_by(User.id)\n    def h(self, session, req):\n        x = req.args['x']  # SEED\n        return self.base_query(session).filter(User.id == x).all()  # SINK\n", W),
        py("A21c clean same-file helper as chain root", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef base(session):\n    return session.query(User).order_by(User.id)\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return base(session).filter(User.id == x).all()  # SINK\n", S),
        py("recall: clean self.base_query method", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass R:\n    def base_query(self, session):\n        return session.query(User).order_by(User.id)\n    def h(self, session, req):\n        x = req.args['x']  # SEED\n        return self.base_query(session).filter(User.id == x).all()  # SINK\n", S),
        py("recall: clean depth-2 helper chain", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef b(session):\n    return session.query(User).order_by(User.id)\ndef a(session):\n    return b(session).order_by(User.name)\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return a(session).filter(User.id == x).all()  # SINK\n", S),
        py("recall: helper with two clean returns", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef base(session, flag):\n    if flag:\n        return session.query(User).order_by(User.id)\n    return session.query(User)\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return base(session, 1).filter(User.id == x).all()  # SINK\n", S),
        py("recall: imported helper stays an opaque root", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nfrom app.q import base\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return base(session).filter(User.id == x).all()  # SINK\n", S),
    ]);
}
